from pathlib import Path
p = Path('lib/config/app_config.dart')
text = p.read_text()
text = text.replace("import 'dart:convert';\nimport '../models/settings.dart';\n", "import 'dart:convert';\nimport '../models/settings.dart';\nimport '../models/driver_profile.dart';\nimport '../services/learning_service.dart';\n")
text = text.replace("  static double speedWarningThreshold = 110.0; // km/h\n\n  // Telegram notification intervals (in seconds)",
"  static double speedWarningThreshold = 110.0; // km/h\n\n  // Adaptive learning\n  static bool adaptiveLearningEnabled = false;\n  static DriverProfile driverProfile = DriverProfile.defaultProfile();\n\n  static double get effectiveSpeedThreshold => adaptiveLearningEnabled && driverProfile.isInitialized ? (speedThreshold * (1 + driverProfile.averageOverSpeedRatio * 0.6)).clamp(speedThreshold, speedThreshold + 25) : speedThreshold;\n\n  static double get effectiveSuddenAccelerationThreshold => adaptiveLearningEnabled && driverProfile.isInitialized ? (suddenAccelerationThreshold + (driverProfile.averageEventRate - 0.02) * 1.5).clamp(1.5, 5.0) : suddenAccelerationThreshold;\n\n  static double get effectiveSuddenBrakingThreshold => adaptiveLearningEnabled && driverProfile.isInitialized ? (suddenBrakingThreshold - (driverProfile.averageEventRate - 0.02) * 1.5).clamp(-5.0, -1.5) : suddenBrakingThreshold;\n\n  static double get effectiveSharpTurnThreshold => adaptiveLearningEnabled && driverProfile.isInitialized ? (sharpTurnThreshold + (driverProfile.averageEventRate - 0.02) * 1.5).clamp(1.5, 5.0) : sharpTurnThreshold;\n\n  // Telegram notification intervals (in seconds)")
p.write_text(text)
